using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Controls.Primitives;
using Microsoft.Windows.Storage.Pickers;
using System.Security.Cryptography;
using System.Text.Json.Nodes;
using TrayAssistant_App.Controls;
using TrayAssistant_App.Models;
using TrayAssistant_App.Services;
using TrayAssistant_App.ViewModels;
namespace TrayAssistant_App;
public sealed partial class MainPage : Page
{
 public TrayViewModel Vm { get; }=new();
 private readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromSeconds(1)};
 private bool loaded,editorOpen;
 public MainPage(){InitializeComponent();LoadingRows.ItemsSource=Enumerable.Range(0,10);Vm.PropertyChanged+=(_,e)=>{if(e.PropertyName is nameof(Vm.IsReady) or nameof(Vm.IsLoading) or nameof(Vm.Error))UpdatePresentation();};UpdatePresentation();Vm.LanguageChanged+=()=>Localization.Apply(this);Vm.ThemeChanged+=index=>{RequestedTheme=index switch{1=>ElementTheme.Light,2=>ElementTheme.Dark,_=>ElementTheme.Default};((FrameworkElement)App.Window.Content).RequestedTheme=RequestedTheme;};Vm.WindowStyleChanged+=(topmost,_)=>{if(App.Window.AppWindow.Presenter is Microsoft.UI.Windowing.OverlappedPresenter presenter)presenter.IsAlwaysOnTop=topmost;};timer.Tick+=async(_,_)=>await Vm.RefreshAsync();Unloaded+=(_,_)=>timer.Stop();}
 private void PopupMica_Open(object sender,object e)=>DispatcherQueue.TryEnqueue(ApplyPopupMica);
 private void ApplyPopupMica(){foreach(var popup in Microsoft.UI.Xaml.Media.VisualTreeHelper.GetOpenPopupsForXamlRoot(XamlRoot))popup.SystemBackdrop=new SoftMicaBackdrop();}
 private async void Page_Loaded(object sender,RoutedEventArgs e){if(!loaded){loaded=true;await Vm.InitializeAsync();RefreshHotkeyBoxes();}Localization.Apply(this);timer.Start();}
 private void Nav_SelectionChanged(NavigationView sender,NavigationViewSelectionChangedEventArgs e){if(IconList==null)return;var tag=(e.SelectedItem as NavigationViewItem)?.Tag?.ToString();UpdatePresentation();SettingsView.Visibility=tag=="settings"?Visibility.Visible:Visibility.Collapsed;DiagnosticsView.Visibility=tag=="diagnostics"?Visibility.Visible:Visibility.Collapsed;}
 private void UpdatePresentation(){if(IconList==null||LoadingList==null)return;bool icons=(Nav.SelectedItem as NavigationViewItem)?.Tag?.ToString()=="icons";IconList.Visibility=icons&&Vm.IsReady?Visibility.Visible:Visibility.Collapsed;LoadingList.Visibility=icons&&Vm.IsLoading?Visibility.Visible:Visibility.Collapsed;ErrorNotice.IsOpen=Vm.Error.Length>0;}
 private async void Icon_NativeAction(object sender,TrayIconActionEventArgs e){if(sender is TrayIconButton{Tag:IconRow row})await Vm.NativeActionAsync(row,e.Action,e.Keyboard,e.X,e.Y);}
 private async void Visibility_Toggled(object sender,RoutedEventArgs e){var toggle=(ToggleSwitch)sender;if(toggle.Tag is IconRow row)await Vm.SetRowVisibilityAsync(row,toggle.IsOn);}
 private async void IconSettings_Click(object sender,RoutedEventArgs e){if(editorOpen||((Button)sender).Tag is not IconRow row)return;Vm.Selected=row;editorOpen=true;var content=(UIElement)IconEditor.Content;IconEditor.Content=null;try{await MicaDialog.ShowAsync(row.Name,content,RequestedTheme,Localization.Text("应用"),Localization.Text("关闭"),async()=>{await Vm.SaveRuleCommand.ExecuteAsync(null);return false;});}finally{IconEditor.Content=content;editorOpen=false;}}
 private async void Editor_Apply(ContentDialog sender,ContentDialogButtonClickEventArgs e){e.Cancel=true;var deferral=e.GetDeferral();try{await Vm.SaveRuleCommand.ExecuteAsync(null);}finally{deferral.Complete();}}
 private async void RestoreAll_Click(object sender,RoutedEventArgs e){try{var result=await Vm.Pipe.RequestAsync("icons.restoreAll");if(result["success"]?.GetValue<bool>()!=true)throw new IOException(result["detail"]?.GetValue<string>());Vm.Status=result["detail"]?.GetValue<string>()??"";await Vm.RefreshAsync();}catch(Exception ex){Vm.ReportError(ex);}}
 [System.Runtime.InteropServices.DllImport("user32.dll")]private static extern short GetKeyState(int key);
 private void HotkeyBox_KeyDown(object sender,Microsoft.UI.Xaml.Input.KeyRoutedEventArgs e){var box=(TextBox)sender;int key=(int)e.Key;if(key is 16 or 17 or 18 or 91 or 92)return;int modifiers=(GetKeyState(17)<0?2:0)|(GetKeyState(18)<0?1:0)|(GetKeyState(16)<0?4:0)|(GetKeyState(91)<0||GetKeyState(92)<0?8:0);int code=key is 8 or 46?0:modifiers==0?0:(modifiers<<16)|key;e.Handled=true;var tag=box.Tag.ToString()!;if(tag=="icon"){Vm.Hotkey=code;Vm.HotkeyText=TrayViewModel.DescribeHotkey(code);}else{Vm.Hotkeys[tag]=code;box.Text=TrayViewModel.DescribeHotkey(code);}}
 private void RefreshHotkeyBoxes(){foreach(var key in new[]{"open","restoreIcons"})if(FindName("Hotkey_"+key) is TextBox box)box.Text=TrayViewModel.DescribeHotkey(Vm.Hotkeys[key]?.GetValue<int>()??0);}
 private async void ReadSystem_Click(object sender,RoutedEventArgs e){try{var result=await Vm.Pipe.RequestAsync("system.read");if(result["success"]?.GetValue<bool>()!=true)throw new IOException(result["detail"]?.GetValue<string>());SystemList.Children.Clear();var names=new[]{"网络","音量","电源","输入法 / 语言","时钟","通知","隐私指示器","开始","快速设置"};foreach(var item in result["data"]!.AsArray()){int id=item!["id"]!.GetValue<int>();var toggle=new ToggleSwitch{Header=Localization.Text(names[id]),OnContent=Localization.Text("显示"),OffContent=Localization.Text("隐藏"),IsOn=item["visible"]!.GetValue<bool>()};Microsoft.UI.Xaml.Automation.AutomationProperties.SetAutomationId(toggle,"System"+id);toggle.Toggled+=async(_,_)=>{try{var read=await Vm.Pipe.RequestAsync("settings.read");var policies=(JsonArray?)read["data"]?["systemControls"]?.DeepClone()??new();for(int n=policies.Count-1;n>=0;n--)if(policies[n]!["id"]!.GetValue<int>()==id)policies.RemoveAt(n);policies.Add(new JsonObject{["id"]=id,["hidden"]=!toggle.IsOn});var response=await Vm.Pipe.RequestAsync("system.apply",new(){["controls"]=policies});if(response["success"]?.GetValue<bool>()!=true)throw new IOException(response["detail"]?.GetValue<string>());Vm.Status=response["detail"]?.GetValue<string>()??"";}catch(Exception ex){Vm.ReportError(ex);}};SystemList.Children.Add(toggle);}}catch(Exception ex){Vm.ReportError(ex);}}
 private async void Export_Click(object sender,RoutedEventArgs e){try{var picker=new FileSavePicker(App.Window.AppWindow.Id){SuggestedFileName="托盘助手配置"};picker.FileTypeChoices.Add("助手配置",new List<string>{".json"});var file=await picker.PickSaveFileAsync();if(file==null)return;var r=await Vm.Pipe.RequestAsync("settings.read");var settings=(JsonObject)r["data"]!.DeepClone();var assets=new JsonObject();foreach(var rule in settings["rules"]!.AsArray())await Embed(rule!.AsObject(),assets);await Embed(settings["ownIcon"]!.AsObject(),assets);settings["assets"]=assets;await File.WriteAllTextAsync(file.Path,settings.ToJsonString(new(){WriteIndented=true}));Vm.Status="配置与图标已导出";}catch(Exception ex){Vm.ReportError(ex);}}
 private static async Task Embed(JsonObject node,JsonObject assets){var path=node["asset"]?.GetValue<string>()??"";if(path.Length==0)return;var bytes=await File.ReadAllBytesAsync(path);var name=Convert.ToHexString(SHA256.HashData(bytes))+Path.GetExtension(path);assets[name]=Convert.ToBase64String(bytes);node["asset"]=name;}
 private async void Import_Click(object sender,RoutedEventArgs e){try{var picker=new FileOpenPicker(App.Window.AppWindow.Id);picker.FileTypeFilter.Add(".json");var file=await picker.PickSingleFileAsync();if(file==null)return;if(new FileInfo(file.Path).Length>96*1024*1024)throw new IOException("配置文件过大");var bundle=JsonNode.Parse(await File.ReadAllTextAsync(file.Path))!.AsObject();if(bundle["schema"]?.GetValue<int>()!=1)throw new IOException("配置版本不兼容");var message=new TextBlock{Text=Localization.English?"This replaces current rules and preferences. The previous configuration is backed up automatically.":"将替换当前规则与偏好。原配置会自动保留为备份。",TextWrapping=TextWrapping.Wrap};if(!await MicaDialog.ShowAsync(Localization.English?"Import configuration?":"导入配置？",message,RequestedTheme,Localization.English?"Import":"导入",Localization.English?"Cancel":"取消",height:240))return;var settings=await BackupService.PrepareImportAsync(bundle);var result=await Vm.Pipe.RequestAsync("settings.import",new(){["settings"]=settings});if(result["success"]?.GetValue<bool>()!=true)throw new IOException(result["detail"]?.GetValue<string>());Vm.Status=Localization.English?"Configuration imported":"配置已导入";await Vm.InitializeAsync();RefreshHotkeyBoxes();}catch(Exception ex){Vm.ReportError(ex);}}
}





